import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Strategies and search audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/STRATEGIES-AND-SEARCH.html"}],["meta",{"property":"og:title","content":"Strategies and search audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/STRATEGIES-AND-SEARCH.html"}],["meta",{"name":"twitter:title","content":"Strategies and search audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/STRATEGIES-AND-SEARCH.md","filePath":"audits/STRATEGIES-AND-SEARCH.md","lastUpdated":1794184492000}`),a={name:`audits/STRATEGIES-AND-SEARCH.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n('<h1 id="strategies-and-search-audit" tabindex="-1">Strategies and search audit <a class="header-anchor" href="#strategies-and-search-audit" aria-label="Permalink to “Strategies and search audit”">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>Reviewed Greedy, GSS, Absolute R, Absolute R+, shared search primitives, search scoring/pruning, path replay, diagnostics, worker orchestration and the test inventory for strategy parity.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to “Findings”">​</a></h2><h3 id="search-01-—-scoped-absolute-r-has-no-default-expansion-budget-or-post-start-execution-timeout" tabindex="-1">SEARCH-01 — Scoped Absolute R+ has no default expansion budget or post-start execution timeout <a class="header-anchor" href="#search-01-—-scoped-absolute-r-has-no-default-expansion-budget-or-post-start-execution-timeout" aria-label="Permalink to “SEARCH-01 — Scoped Absolute R+ has no default expansion budget or post-start execution timeout”">​</a></h3><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/search-strategy-base.js#L1342-L1357" target="_blank" rel="noreferrer">SearchStrategyBase constructor L1342-L1357</a> defaults <code>max_decisions</code> to <code>null). [GAML run loop L1246-L1284](https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/search-strategy-base.js#L1246-L1284) continues while the beam is non-empty and only enforces a cap when one is configured. The UI leaves the decision-cap field blank by default ([app.js L76](https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L76)). The worker runner clears its handshake timer after the worker sends </code>started` (<a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/simulation-runner.js#L184-L193" target="_blank" rel="noreferrer">simulation-runner.js L184-L193</a>); there is no execution deadline after that acknowledgement.</p><p><strong>Impact:</strong> a large or pathological scenario can keep a worker occupied for an unbounded duration. The UI shows elapsed time but has no explicit cancel action. A worker protects the main thread from synchronous search work, but it does not guarantee bounded resource consumption or a clear user recovery path.</p><p><strong>Recommendation:</strong> add a documented default decision/time budget for browser runs, expose “cancel”, and enforce a post-start deadline. When a budget stops search, surface <code>optimality_proven: false</code> and the exact budget/expanded-state count. Keep an explicit opt-in for unbounded CLI runs if needed.</p><h3 id="search-02-—-large-strategy-modules-concentrate-several-independent-responsibilities" tabindex="-1">SEARCH-02 — Large strategy modules concentrate several independent responsibilities <a class="header-anchor" href="#search-02-—-large-strategy-modules-concentrate-several-independent-responsibilities" aria-label="Permalink to “SEARCH-02 — Large strategy modules concentrate several independent responsibilities”">​</a></h3><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/search-strategy-base.js" target="_blank" rel="noreferrer">search-strategy-base.js</a> is a large shared module containing state representation, option selection, cache management, branch expansion, bounds, scoring, beam search, exhaustive search, goal evaluation and path replay. <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/gss.js" target="_blank" rel="noreferrer">gss.js</a> is also a large strategy module with recursive planning and execution logic.</p><p><strong>Impact:</strong> changes to one search concern can affect several modes. The cost is not merely file length: it is the number of domain responsibilities and invariants that must be held in working memory during a change.</p><p><strong>Recommendation:</strong> after correctness findings are resolved and parity tests are stable, extract cohesive modules such as search-state/keying, bounds and scoring, expansion generation, beam/exhaustive orchestration, and path replay. Keep strategy contracts small and avoid splitting into one-function files.</p><h3 id="search-03-—-gss-and-search-paths-contain-independent-future-planning-logic-that-needs-continued-parity-protection" tabindex="-1">SEARCH-03 — GSS and search paths contain independent future-planning logic that needs continued parity protection <a class="header-anchor" href="#search-03-—-gss-and-search-paths-contain-independent-future-planning-logic-that-needs-continued-parity-protection" aria-label="Permalink to “SEARCH-03 — GSS and search paths contain independent future-planning logic that needs continued parity protection”">​</a></h3><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/gss.js" target="_blank" rel="noreferrer">gss.js</a> contains its own future liquidity reservation, plan generation and recursive wait/reforecast paths; <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/strategies/search-strategy-base.js" target="_blank" rel="noreferrer">search-strategy-base.js</a> also constructs hypothetical future states before replaying a selected path through <code>SimulationEngine</code>.</p><p><strong>Impact:</strong> a financial rule added to the authoritative runtime can be omitted or implemented differently in a hypothetical planner. The replay step is a useful safety boundary, but it does not prove that candidate generation explores every valid path.</p><p><strong>Recommendation:</strong> keep one authoritative execution engine. Treat planners as candidate generators and add parity fixtures for every new event type, outflow policy, fee rule, payout type and account constraint. Where a planner intentionally approximates, document the approximation and diagnostics.</p><h2 id="existing-strengths" tabindex="-1">Existing strengths <a class="header-anchor" href="#existing-strengths" aria-label="Permalink to “Existing strengths”">​</a></h2><ul><li>Greedy is an explicit baseline and Absolute R+ compares candidate paths against it before selection.</li><li>Absolute R+ exposes beam pruning, local-combination pruning, expanded states, cache statistics, search settings and optimality status.</li><li>The search code uses bounded caches and state memoization rather than unbounded memo maps.</li><li>Path replay through <code>SimulationEngine.runUnfinalized</code> checks that selected candidate actions are executable by the runtime.</li><li>The tests include legacy-oracle and parity suites for Greedy, GSS and search strategies, plus search primitives and goal-objective tests.</li></ul><h2 id="strategy-specific-notes" tabindex="-1">Strategy-specific notes <a class="header-anchor" href="#strategy-specific-notes" aria-label="Permalink to “Strategy-specific notes”">​</a></h2><ul><li><strong>Greedy:</strong> suitable as a fast heuristic, not a proof of global optimality. The UI description correctly communicates that limitation.</li><li><strong>GSS:</strong> preserve its liquidity reservation and split/consolidate constraints with targeted regression fixtures. Avoid treating its best plan as a global optimum unless the search space is formally covered.</li><li><strong>Absolute R:</strong> exhaustive branch-and-bound can be expensive; it is CLI-only in the browser workflow and should remain clearly identified as a potentially costly exact search.</li><li><strong>Absolute R+:</strong> beam search is bounded by width and optional decision/local-branch caps. Beam pruning means a globally optimal result is not generally guaranteed; the result&#39;s optimality diagnostic must remain visible.</li></ul><h2 id="tests-to-add" tabindex="-1">Tests to add <a class="header-anchor" href="#tests-to-add" aria-label="Permalink to “Tests to add”">​</a></h2><ul><li>A deterministic scenario that reaches the default browser search budget and proves graceful termination.</li><li>Cancellation during a long-running worker computation and immediate recovery on the next submission.</li><li>Parity cases for new fee, payout, eligibility and outflow rules across GSS/search planning and runtime replay.</li><li>Regression tests that assert diagnostics correctly distinguish exhaustive proof, beam pruning and decision-budget termination.</li></ul>',23)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};